function evaluateCell(a,trail=new Set()){const v=raw(a);if(!v.startsWith('='))return v;if(trail.has(a))return '#CIRCULAR!';try{const t=tokenize(v.slice(1));let p=0;const next=()=>t[p++],peek=()=>t[p];const num=x=>{if(typeof x==='string'&&x.startsWith('#'))throw Error(x);const n=Number(x);return Number.isFinite(n)?n:0};const ref=x=>{const q=parseAddress(x);if(!q)throw Error('#FORMULA!');return evaluateCell(x,new Set([...trail,a]))};function primary(){let x=next();if(x==='('){let v=expr();if(next()!==')')throw Error('#FORMULA!');return v}if(/^\d/.test(x))return +x;if(/^[A-Z]+\d+$/.test(x))return ref(x);if(FUNCS.includes(x)){if(next()!=='(')throw Error('#FORMULA!');let vals=[];if(peek()!==')')while(true){let first=next();if(/^[A-Z]+\d+$/.test(first)&&peek()===':'){next();let last=next(),a1=parseAddress(first),a2=parseAddress(last);if(!a2)throw Error('#FORMULA!');for(let r=Math.min(a1.r,a2.r);r<=Math.max(a1.r,a2.r);r++)for(let c=Math.min(a1.c,a2.c);c<=Math.max(a1.c,a2.c);c++)vals.push(ref(address(r,c)))}else{p--;vals.push(expr())}if(peek()!==',')break;next()}if(next()!==')')throw Error('#FORMULA!');let ns=vals.map(num);if(x==='SUM')return ns.reduce((a,b)=>a+b,0);if(x==='COUNT')return vals.filter(y=>y!==''&&Number.isFinite(Number(y))).length;if(!ns.length)return 0;if(x==='AVG')return ns.reduce((a,b)=>a+b,0)/ns.length;if(x==='MIN')return Math.min(...ns);return Math.max(...ns)}throw Error('#FORMULA!')}function unary(){if(peek()==='-'){next();return-num(unary())}if(peek()==='+'){next();return num(unary())}return primary()}function mul(){let v=unary();while(peek()==='*'||peek()==='/'){let op=next(),n=num(unary());if(op==='/'&&n===0)throw Error('#DIV/0!');v=op==='*'?num(v)*n:num(v)/n}return v}function expr(){let v=mul();while(peek()==='+'||peek()==='-'){let op=next(),n=num(mul());v=op==='+'?num(v)+n:num(v)-n}return v}let result=expr();if(p!==t.length)throw Error('#FORMULA!');return String(Number.isFinite(result)?Math.round(result*1e10)/1e10:result)}catch(e){return e.message.startsWith('#')?e.message:'#FORMULA!'}}
function display(a){const v=raw(a);return v.startsWith('=')?evaluateCell(a):v}
function buildGrid(){const g=$('grid');g.innerHTML='<div class="head corner"></div>';for(let c=1;c<=COLS;c++){const d=document.createElement('div');d.className='head colhead';d.textContent=colName(c);g.append(d)}for(let r=1;r<=ROWS;r++){const h=document.createElement('div');h.className='head rowhead';h.textContent=r;g.append(h);for(let c=1;c<=COLS;c++){const d=document.createElement('div');d.className='cell';d.dataset.r=r;d.dataset.c=c;d.id='cell-'+address(r,c);d.setAttribute('role','gridcell');g.append(d)}}render()}
function render(){if(!state.sheet)return;const b=bounds();for(let r=1;r<=ROWS;r++)for(let c=1;c<=COLS;c++){const a=address(r,c),d=$('cell-'+a),v=display(a);d.textContent=v;d.title=raw(a);d.className='cell'+(r>=b.r1&&r<=b.r2&&c>=b.c1&&c<=b.c2?' selected':'')+(r===state.focus.r&&c===state.focus.c?' active':'')+(String(v).startsWith('#')?' formula-error':'')+(state.conflicts.has(a)?' conflict':'')}const a=address(state.focus.r,state.focus.c);$('nameBox').value=rangeText();if(document.activeElement!==$('formula'))$('formula').value=raw(a);$('undo').disabled=!state.undo.length;$('redo').disabled=!state.redo.length;renderRemote()}
function select(r,c,extend=false){r=Math.max(1,Math.min(ROWS,r));c=Math.max(1,Math.min(COLS,c));if(!extend)state.anchor={r,c};state.focus={r,c};render();$('cell-'+address(r,c)).scrollIntoView({block:'nearest',inline:'nearest'});updatePresence()}
function snapshotAction(changes,label='Edit'){const clean=changes.filter(x=>x.old!==x.value);if(!clean.length)return;for(const x of clean){if(x.value==='')delete state.sheet.cells[x.a];else state.sheet.cells[x.a]=x.value}state.undo.push({changes:clean,label});state.redo=[];markDirty();render()}
function setSingle(value){const a=address(state.focus.r,state.focus.c);snapshotAction([{a,old:raw(a),value}],`Edit ${a}`)}
function markDirty(){state.dirty=true;state.conflicts.clear();setStatus('Dirty','dirty');clearTimeout(state.saveTimer);state.saveTimer=setTimeout(save,900)}
function setStatus(text,kind=''){$('saveState').textContent=text;$('saveState').className='state '+kind}
function message(x){$('message').textContent=x||''}
async function api(url,opts){const r=await fetch(url,opts),data=await r.json();if(!r.ok)throw Object.assign(Error(data.error||'Request failed'),{data,status:r.status});return data}
async function save(){if(state.saving||!state.dirty)return;state.saving=true;setStatus('Saving…');try{const data=await api(`/api/workbooks/${state.workbook.id}/save`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({baseRevision:state.revision,userId:state.userId,workbook:state.workbook})});state.workbook=clone(data.workbook);state.sheet=state.workbook.sheets[0];state.base=clone(state.workbook);state.revision=data.revision;state.dirty=false;state.conflicts.clear();setStatus(`Saved · r${state.revision}`);message('');render()}catch(e){setStatus('Save failed','error');message(e.message);if(e.data?.conflicts){e.data.conflicts.forEach(a=>state.conflicts.add(a));render()}}finally{state.saving=false}}
function undo(){const x=state.undo.pop();if(!x)return;const reverse=x.changes.map(c=>({a:c.a,old:raw(c.a),value:c.old}));for(const c of reverse)c.value===''?delete state.sheet.cells[c.a]:state.sheet.cells[c.a]=c.value;state.redo.push(x);markDirty();render()}
function redo(){const x=state.redo.pop();if(!x)return;for(const c of x.changes)c.value===''?delete state.sheet.cells[c.a]:state.sheet.cells[c.a]=c.value;state.undo.push(x);markDirty();render()}
function matrix(){const b=bounds(),m=[];for(let r=b.r1;r<=b.r2;r++){let row=[];for(let c=b.c1;c<=b.c2;c++)row.push(raw(address(r,c)));m.push(row)}return m}
async function copy(cut=false){await navigator.clipboard.writeText(matrix().map(r=>r.join('\t')).join('\n'));if(cut)clearRange()}
function pasteText(text){const rows=text.replace(/\r/g,'').split('\n').filter((x,i,a)=>i<a.length-1||x!=='').map(x=>x.includes('\t')?x.split('\t'):x.includes(',')?x.split(','):[x]);let changes=[];for(let i=0;i<rows.length;i++)for(let j=0;j<rows[i].length;j++){const a=address(state.anchor.r+i,state.anchor.c+j);if(state.anchor.r+i<=ROWS&&state.anchor.c+j<=COLS)changes.push({a,old:raw(a),value:rows[i][j]})}snapshotAction(changes,'Paste')}
function clearRange(){let changes=[];const b=bounds();for(let r=b.r1;r<=b.r2;r++)for(let c=b.c1;c<=b.c2;c++){const a=address(r,c);changes.push({a,old:raw(a),value:''})}snapshotAction(changes,'Clear range')}
function shiftFormula(v,dr,dc){return v.replace(/\b([A-Z]+)([1-9]\d*)\b/g,(m,col,row)=>{let p=parseAddress(col+row);return address(Math.max(1,p.r+dr),Math.max(1,p.c+dc))})}
function fill(direction){const b=bounds();if((direction==='down'&&b.r1===b.r2)||(direction==='right'&&b.c1===b.c2))return message('Select a multi-cell range to fill.');let changes=[];if(direction==='down')for(let c=b.c1;c<=b.c2;c++){const first=raw(address(b.r1,c)),second=b.r1<b.r2?raw(address(b.r1+1,c)):'';let step=!isNaN(first)&&first!==''&&!isNaN(second)&&second!==''?Number(second)-Number(first):null;for(let r=b.r1+1;r<=b.r2;r++){let value=step===null?(first.startsWith('=')?shiftFormula(first,r-b.r1,0):first):String(Number(first)+step*(r-b.r1));const a=address(r,c);changes.push({a,old:raw(a),value})}}else for(let r=b.r1;r<=b.r2;r++){const first=raw(address(r,b.c1)),second=raw(address(r,b.c1+1));let step=!isNaN(first)&&first!==''&&!isNaN(second)&&second!==''?Number(second)-Number(first):null;for(let c=b.c1+1;c<=b.c2;c++){let value=step===null?(first.startsWith('=')?shiftFormula(first,0,c-b.c1):first):String(Number(first)+step*(c-b.c1));const a=address(r,c);changes.push({a,old:raw(a),value})}}snapshotAction(changes,'Fill')}
